const normalizeContentPart = (part: MessageContent): TextContent | ImageContent | FileContent => {
  if (typeof part === "string") {
    return { type: "text", text: part };
  }

  if (part.type === "text") {
    return part;
  }

  if (part.type === "image_url") {
    return part;
  }

  if (part.type === "file_url") {
    return part;
  }

  throw new Error("Unsupported message content part");
};

const normalizeMessage = (message: Message) => {
  const { role, name, tool_call_id } = message;

  if (role === "tool" || role === "function") {
    const content = ensureArray(message.content)
      .map((part) => (typeof part === "string" ? part : JSON.stringify(part)))
      .join("\n");

    return {
      role,
      name,
      tool_call_id,
      content,
    };
  }

  const contentParts = ensureArray(message.content).map(normalizeContentPart);

  // If there's only text content, collapse to a single string for compatibility
  if (contentParts.length === 1 && contentParts[0].type === "text") {
    return {
      role,
      name,
      content: contentParts[0].text,
    };
  }

  return {
    role,
    name,
    content: contentParts,
  };
};

const normalizeToolChoice = (
  toolChoice: ToolChoice | undefined,
  tools: Tool[] | undefined,
): "none" | "auto" | ToolChoiceExplicit | undefined => {
  if (!toolChoice) return undefined;

  if (toolChoice === "none" || toolChoice === "auto") {
    return toolChoice;
  }

  if (toolChoice === "required") {
    if (!tools || tools.length === 0) {
      throw new Error("tool_choice 'required' was provided but no tools were configured");
    }

    if (tools.length > 1) {
      throw new Error(
        "tool_choice 'required' needs a single tool or specify the tool name explicitly",
      );
    }

    return {
      type: "function",
      function: { name: tools[0].function.name },
    };
  }

  if ("name" in toolChoice) {
    return {
      type: "function",
      function: { name: toolChoice.name },
    };
  }

  return toolChoice;
};

const resolveApiUrl = () =>
  ENV.forgeApiUrl && ENV.forgeApiUrl.trim().length > 0
    ? ${ENV.forgeApiUrl.replace(/\/$/, "")}/v1/chat/completions
    : "";

const assertApiKey = () => {
  if (!ENV.forgeApiKey) {
    throw new Error("OPENAI_API_KEY is not configured");
  }
};

const normalizeResponseFormat = ({
  responseFormat,
  response_format,
  outputSchema,
  output_schema,
}: {
  responseFormat?: ResponseFormat;
  response_format?: ResponseFormat;
  outputSchema?: OutputSchema;
  output_schema?: OutputSchema;
}):
  | { type: "json_schema"; json_schema: JsonSchema }
  | { type: "text" }
  | { type: "json_object" }
  | undefined => {
  const explicitFormat = responseFormat || response_format;
  if (explicitFormat) {
    if (explicitFormat.type === "json_schema" && !explicitFormat.json_schema?.schema) {
      throw new Error("responseFormat json_schema requires a defined schema object");
    }
    return explicitFormat;
  }

  const schema = outputSchema || output_schema;
  if (!schema) return undefined;

  if (!schema.name || !schema.schema) {
    throw new Error("outputSchema requires both name and schema");
  }

  return {
    type: "json_schema",
    json_schema: {
      name: schema.name,
      schema: schema.schema,
      ...(typeof schema.strict === "boolean" ? { strict: schema.strict } : {}),
    },
  };
};

export async function invokeLLM(params: InvokeParams): Promise<InvokeResult> {
  assertApiKey();

  const {
    messages,
    tools,
    toolChoice,
    tool_choice,
    outputSchema,
    output_schema,
    responseFormat,
    response_format,
  } = params;

  const payload: Record<string, unknown> = {
    model: "gemini2.5flash",
    messages: messages.map(normalizeMessage),
  };

  if (tools && tools.length > 0) {
    payload.tools = tools;
  }

  const normalizedToolChoice = normalizeToolChoice(toolChoice || tool_choice, tools);
  if (normalizedToolChoice) {
    payload.tool_choice = normalizedToolChoice;
  }

  payload.max_tokens = 32768;
  payload.thinking = {
    budget_tokens: 128,
  };

  const normalizedResponseFormat = normalizeResponseFormat({
    responseFormat,
    response_format,
    outputSchema,
    output_schema,
  });

  if (normalizedResponseFormat) {
    payload.response_format = normalizedResponseFormat;
  }

  const response = await fetch(resolveApiUrl(), {
    method: "POST",
    headers: {
      "contenttype": "application/json",
      authorization: Bearer ${ENV.forgeApiKey},
    },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(LLM invoke failed: ${response.status} ${response.statusText} – ${errorText});
  }

  return (await response.json()) as InvokeResult;
}


A megosztott forráskód egy TypeScript nyelven írt modul, amely egy LLM (Large Language Model / nagy nyelvi modell) APIhívásának előkészítésére, normalizálására és végrehajtására szolgál. A kód kifejezetten az OpenAIkompatibilis formátumot célozza meg (a végpont alapján egy egyedi környezetet, a forge.manus.im APIt), a háttérben pedig alapértelmezetten a gemini2.5flash modellt hívja meg.
A teljes kódot sorról sorra átolvasva és elemezve az alábbi fő részekre és logikára tagolható:
 1. Típusdefiníciók (Types)
A kód első fele szigorú típusbiztonságot ad az adatszerkezeteknek:
  Role: A beszélgetés résztvevői (system, user, assistant, tool, function).
  Tartalomtípusok: Külön típusokat definiál a szöveges (TextContent), képi (ImageContent – automatikus/alacsony/magas részletességgel) és fájlalapú (FileContent – pl. hangfájlok, PDF, videó) bemenetekhez.
  Message & Tool: Definiálja, hogyan néz ki egy üzenet objektum, valamint az LLM által meghívható külső eszközök (funkciók) struktúrája és paraméterezése.
  Eszközválasztás (ToolChoice...): Kezeli, hogy az LLM kötelezően használjone egy eszközt, vagy automatikusan döntsön.
  InvokeParams & InvokeResult: A függvénynek átadható bemeneti paraméterek (pl. camelCase és snake_case támogatással: maxTokens/max_tokens) és az API által visszaadott válasz pontos szerkezete (tokenhasználattal, befejezési okokkal).
  Strukturált kimenetek (JsonSchema, OutputSchema, ResponseFormat): A JSON formátumú válaszok kikényszerítésére szolgáló sémák leírása.
 2. Segédfüggvények (Helper Functions)
A belső használatú függvények az adatok tisztításáért és formázásáért felelnek az APIhívás előtt:
  ensureArray: Garantálja, hogy a bemenet tömb formátumú legyen.
  normalizeContentPart: Ellenőrzi és egységes formára hozza a különböző médiatípusokat. Ha sima szöveg érkezik, objektummá alakítja, ismeretlen típus esetén pedig hibát dob.
  normalizeMessage: Az üzeneteket készíti fel. Ha a szerepkör tool vagy function, a tartalmat szöveggé vagy JSONstringgé fűzi össze. Ha a normál üzenetben csak egyetlen sima szöveges elem van, azt visszatömöríti egy egyszerű stringgé a jobb kompatibilitás érdekében.
  normalizeToolChoice: Validálja és átalakítja az eszközmeghívási szabályokat. Ha a required (kötelező) opció van megadva, ellenőrzi, hogy pontosan egy eszköz álle rendelkezésre; ha több vagy nulla, hibát dob.
  resolveApiUrl: Meghatározza az API végpontját. Ha a környezeti változókban (ENV.forgeApiUrl) meg van adva egyedi cím, azt formázza meg, egyébként a  alapértelmezett címre küldi a kérést.
  assertApiKey: Biztonsági ellenőrzés; hibát dob (OPENAI_API_KEY is not configured), ha hiányzik az API kulcs a környezeti változókból.
  normalizeResponseFormat: Kezeli a várt válaszformátumot. Összefésüli a responseFormat és outputSchema paramétereket, validálja azokat (pl. hogy a séma tartalmaze nevet és leírást), majd visszaadja a megfelelő JSONséma konfigurációt.
 3. Fő funkció: invokeLLM
Ez a modul egyetlen exportált aszinkron függvénye, amely a tényleges hívást végzi:
 1. Validálás: Legelőször ellenőrzi az API kulcs meglétét.
 2. Payload összeállítása: Létrehozza a küldendő adatcsomagot. Fixen beégeti a gemini2.5flash modellt, a max_tokens értékét 32 768ra, valamint beállít egy 128 tokenes gondolkodási büdzsét (thinking.budget_tokens: 128).
 3. Kérés elküldése: A fetch API segítségével POST kérést indít a végpontra, beállítva a JSON fejlécet és a Bearer tokent (API kulcsot).
 4. Hibakezelés és visszatérés: Ha a szerver válasza nem sikeres (!response.ok), kiolvassa a hiba szövegét és részletes hibaüzenetet dob. Sikeres hívás esetén a választ JSONná alakítva, InvokeResult típusként adja vissza.
 Összegzés
Ez egy professzionálisan megírt, robusztus interfész (wrapper) egy LLM kiszolgálóhoz, amely rugalmasan kezeli a multimodális bemeneteket (szöveg, kép, hang, PDF), támogatja a funkcióhívásokat (tool calling), a szigorú JSON kimeneteket, és gondoskodik a fejlesztői paraméterek (camelCase/snake_case) egységesítéséről.


