const std = @import("std");

const request_body =
    "{\"messages\":[{\"role\":\"system\",\"content\":\"\"},{\"role\":\"user\",\"content\":[{\"type\":\"image_url\",\"image_url\":{\"url\":\"image/jpeg;base64,<base64encodedimage>\"}}]}],\"model\":\"gemma431b\",\"stream\":true,\"max_completion_tokens\":40000,\"temperature\":0,\"top_p\":0.95}";

fn startsWith(bytes: []const u8, prefix: []const u8) bool {
    if (bytes.len < prefix.len) return false;
    for (prefix, 0..) |byte, index| {
        if (bytes[index] != byte) return false;
    }
    return true;
}

fn equals(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |a_byte, b_byte| {
        if (a_byte != b_byte) return false;
    }
    return true;
}

fn findByte(bytes: []const u8, start: usize, needle: u8) ?usize {
    var index = start;
    while (index < bytes.len) : (index += 1) {
        if (bytes[index] == needle) return index;
    }
    return null;
}

fn processEvent(
    allocator: std.mem.Allocator,
    io: std.Io,
     []const u8,
) !bool {
    if (equals(data, "[DONE]")) return true;
    if (data.len == 0) return false;

    var parsed = std.json.parseFromSlice(std.json.Value, allocator, data, .{}) catch
        return error.InvalidStreamingResponse;
    defer parsed.deinit();

    const root = switch (parsed.value) {
        .object => |object| object,
        else => return error.InvalidStreamingResponse,
    };

    if (root.get("error")) |error_value| {
        try std.Io.File.stderr().writeStreamingAll(io, "Cerebras API error: ");
        switch (error_value) {
            .object => |error_object| {
                if (error_object.get("message")) |message_value| {
                    switch (message_value) {
                        .string => |message| try std.Io.File.stderr().writeStreamingAll(io, message),
                        else => try std.Io.File.stderr().writeStreamingAll(io, data),
                    }
                } else {
                    try std.Io.File.stderr().writeStreamingAll(io, data);
                }
            },
            .string => |message| try std.Io.File.stderr().writeStreamingAll(io, message),
            else => try std.Io.File.stderr().writeStreamingAll(io, data),
        }
        try std.Io.File.stderr().writeStreamingAll(io, "\n");
        return error.CerebrasApiError;
    }

    const choices_value = root.get("choices") orelse return false;
    const choices = switch (choices_value) {
        .array => |array| array.items,
        else => return error.InvalidStreamingResponse,
    };

    if (choices.len == 0) return false;

    const choice = switch (choices[0]) {
        .object => |object| object,
        else => return error.InvalidStreamingResponse,
    };

    const delta_value = choice.get("delta") orelse return false;
    const delta = switch (delta_value) {
        .object => |object| object,
        else => return error.InvalidStreamingResponse,
    };

    const content_value = delta.get("content") orelse return false;
    switch (content_value) {
        .string => |content| {
            if (content.len != 0) {
                try std.Io.File.stdout().writeStreamingAll(io, content);
            }
        },
        .null => {},
        else => {},
    }

    return false;
}

fn consumeSseLine(
    event_ std.ArrayList(u8),
    allocator: std.mem.Allocator,
    io: std.Io,
    raw_line: []const u8,
) !bool {
    var line = raw_line;
    if (line.len != 0 and line[line.len  1] == '\r') {
        line = line[0 .. line.len  1];
    }

    if (line.len == 0) {
        if (event_data.items.len == 0) return false;
        const done = try processEvent(allocator, io, event_data.items);
        event_data.clearRetainingCapacity();
        return done;
    }

    if (line[0] == ':') return false;

    if (startsWith(line, "")) {
        var value = line[5..];
        if (value.len != 0 and value[0] == ' ') {
            value = value[1..];
        }
        if (event_data.items.len != 0) {
            try event_data.append(allocator, '\n');
        }
        try event_data.appendSlice(allocator, value);
    }

    return false;
}

fn writeErrorResponse(
    response: std.http.Client.Response,
    io: std.Io,
) !void {
    var transfer_buffer: [8192]u8 = undefined;
    var read_buffer: [8192]u8 = undefined;
    const reader = response.reader(&transfer_buffer);

    while (true) {
        const count = try reader.readSliceShort(&read_buffer);
        if (count == 0) break;
        try std.Io.File.stderr().writeStreamingAll(io, read_buffer[0..count]);
    }

    try std.Io.File.stderr().writeStreamingAll(io, "\n");
}

pub fn main(init: std.process.Init) !void {
    const allocator = init.gpa;
    const io = init.io;

    const api_key = init.environ_map.get("CEREBRAS_API_KEY") orelse {
        try std.Io.File.stderr().writeStreamingAll(
            io,
            "CEREBRAS_API_KEY environment variable is not set\n",
        );
        return error.MissingCerebrasApiKey;
    };

    if (api_key.len == 0) {
        try std.Io.File.stderr().writeStreamingAll(
            io,
            "CEREBRAS_API_KEY environment variable is empty\n",
        );
        return error.MissingCerebrasApiKey;
    }

    const authorization = try std.fmt.allocPrint(
        allocator,
        "Bearer {s}",
        .{api_key},
    );
    defer allocator.free(authorization);

    var client: std.http.Client = .{
        .allocator = allocator,
        .io = io,
        .read_buffer_size = 65536,
    };
    defer client.deinit();

    const uri: std.Uri = .{
        .scheme = "https",
        .host = .{ .percent_encoded = "api.cerebras.ai" },
        .port = 443,
        .path = .{ .percent_encoded = "/v1/chat/completions" },
    };

    const extra_headers = [_]std.http.Header{
        .{
            .name = "accept",
            .value = "text/eventstream",
        },
    };

    var request = try client.request(.POST, uri, .{
        .headers = .{
            .authorization = .{ .override = authorization },
            .content_type = .{ .override = "application/json" },
            .accept_encoding = .{ .override = "identity" },
        },
        .extra_headers = &extra_headers,
    });
    defer request.deinit();

    try request.sendBodyComplete(@constCast(request_body));

    var redirect_buffer: [65536]u8 = undefined;
    var response = try request.receiveHead(&redirect_buffer);

    const status_code = @intFromEnum(response.head.status);
    if (status_code < 200 or status_code >= 300) {
        const status_message = try std.fmt.allocPrint(
            allocator,
            "Cerebras API request failed with HTTP status {d}\n",
            .{status_code},
        );
        defer allocator.free(status_message);
        try std.Io.File.stderr().writeStreamingAll(io, status_message);
        try writeErrorResponse(&response, io);
        return error.CerebrasApiRequestFailed;
    }

    var transfer_buffer: [16384]u8 = undefined;
    var read_buffer: [16384]u8 = undefined;
    const response_reader = response.reader(&transfer_buffer);

    var pending: std.ArrayList(u8) = .empty;
    defer pending.deinit(allocator);

    var event_ std.ArrayList(u8) = .empty;
    defer event_data.deinit(allocator);

    var done = false;

    while (!done) {
        const count = try response_reader.readSliceShort(&read_buffer);
        if (count == 0) break;

        try pending.appendSlice(allocator, read_buffer[0..count]);

        var consumed: usize = 0;
        while (findByte(pending.items, consumed, '\n')) |newline_index| {
            const line = pending.items[consumed..newline_index];
            consumed = newline_index + 1;

            if (try consumeSseLine(&event_data, allocator, io, line)) {
                done = true;
                break;
            }
        }

        if (consumed != 0) {
            const remaining = pending.items.len  consumed;
            var index: usize = 0;
            while (index < remaining) : (index += 1) {
                pending.items[index] = pending.items[consumed + index];
            }
            pending.items.len = remaining;
        }
    }

    if (!done and pending.items.len != 0) {
        done = try consumeSseLine(
            &event_data,
            allocator,
            io,
            pending.items,
        );
    }

    if (!done and event_data.items.len != 0) {
        _ = try processEvent(allocator, io, event_data.items);
    }
}
